import consts, { DatepickerView } from './common/consts';
import {
    createElement,
    classNames,
    getParsedDate,
    isSameDate,
    isDateSmaller,
    isDateBigger,
    isDateBetween,
} from './common/utils';
import  { DatepickerOptions } from './Default';

import './DatepickerCell.scss';

// Extend the default HTMLElement to allow the custom adpCell property
export interface AdpHTMLCellElement extends HTMLElement {
    adpCell?: DatepickerCell;
}

interface DatepickerCellArgs {
    type: DatepickerView;
    date: Date;
    dp: any; 
    opts: DatepickerOptions;
    body: any; 
}

export default class DatepickerCell {
    type: DatepickerView;
    singleType: string;
    date: Date;
    dp: any;
    opts: DatepickerOptions;
    body: any;
    customData: any = false;
    $cell!: AdpHTMLCellElement;
    focused = false;
    selected = false;

    constructor({ type, date, dp, opts, body }: DatepickerCellArgs) {
        this.type = type;
        this.singleType = this.type.slice(0, -1); // days -> day
        this.date = date;
        this.dp = dp;
        this.opts = opts;
        this.body = body;

        this.init();
    }

    init(): void {
        const { onRenderCell } = this.opts;

        if (onRenderCell) {
            this.customData = onRenderCell({
                date: this.date,
                cellType: this.singleType,
                datepicker: this.dp,
            });
        }

        this._createElement();
        this._bindDatepickerEvents();

        this.render();
        if (this.customData?.disabled) {
            this.dp.disableDate(this.date);
        } else if (this.customData?.disabled === false) {
            this.dp.enableDate(this.date);
        }
    }

    _bindDatepickerEvents(): void {
        this.dp.on(consts.eventChangeSelectedDate, this.onChangeSelectedDate);
        this.dp.on(consts.eventChangeFocusDate, this.onChangeFocusDate);
    }

    unbindDatepickerEvents(): void {
        this.dp.off(consts.eventChangeSelectedDate, this.onChangeSelectedDate);
        this.dp.off(consts.eventChangeFocusDate, this.onChangeFocusDate);
    }

    _createElement(): void {
        const { year, month, fullMonth, date, fullDate } = getParsedDate(this.date);
        const extraAttrs = this.customData?.attrs || {};

        this.$cell = createElement({
            attrs: {
                'data-year': year,
                'data-month': month,
                'data-date': date,
                'data-iso-date': `${year}-${fullMonth}-${fullDate}`,
                ...extraAttrs,
            }
        }) as AdpHTMLCellElement;
        
        this.$cell.adpCell = this;
    }

    _getClassName(): string[] {
        const currentDate = new Date();
        const { selectOtherMonths, selectOtherYears } = this.opts;
        const { minDate, maxDate, isDateDisabled } = this.dp;
        const { day } = getParsedDate(this.date);
        const isOutOfMinMaxRange = this._isOutOfMinMaxRange();
        const isDisabled = isDateDisabled(this.date);

        const classNameCommon = classNames(
            'datepicker-cell',
            `-${this.singleType}-`,
            {
                '-current-': isSameDate(currentDate, this.date, this.type),
                '-min-date-': minDate && isSameDate(minDate, this.date, this.type),
                '-max-date-': maxDate && isSameDate(maxDate, this.date, this.type),
            }
        );
        
        let classNameType = '';

        switch (this.type) {
            case consts.days:
                classNameType = classNames({
                    '-weekend-': this.dp.isWeekend(day),
                    '-other-month-': this.isOtherMonth,
                    '-disabled-': (this.isOtherMonth && !selectOtherMonths) || isOutOfMinMaxRange || isDisabled
                });
                break;
            case consts.months:
                classNameType = classNames({
                    '-disabled-': isOutOfMinMaxRange
                });
                break;
            case consts.years:
                classNameType = classNames({
                    '-other-decade-': this.isOtherDecade,
                    '-disabled-': isOutOfMinMaxRange || (this.isOtherDecade && !selectOtherYears)
                });
                break;
        }

        return classNames(classNameCommon, classNameType, this.customData?.classes).split(' ');
    }

    _getHtml(): string {
        const { year, month, date } = getParsedDate(this.date);
        const { showOtherMonths, showOtherYears, monthsField } = this.opts;

        if (this.customData?.html) {
            return this.customData.html;
        }

        switch (this.type) {
            case consts.days:
                return !showOtherMonths && this.isOtherMonth ? '' : date.toString();
            case consts.months:
                return this.dp.locale[monthsField || 'monthsShort'][month];
            case consts.years:
                return !showOtherYears && this.isOtherDecade ? '' : year.toString();
            default:
                return '';
        }
    }

    _isOutOfMinMaxRange(): boolean {
        const { minDate, maxDate } = this.dp;
        const { type, date: cellDate } = this;
        const { month, year, date } = getParsedDate(cellDate);
        const isDay = type === consts.days;
        const isYear = type === consts.years;

        const cellMinDate = minDate
            ? new Date(year, isYear ? minDate.getMonth() : month, isDay ? date : minDate.getDate())
            : false;
        const cellMaxDate = maxDate
            ? new Date(year, isYear ? maxDate.getMonth() : month, isDay ? date : maxDate.getDate())
            : false;

        if (minDate && maxDate && cellMinDate && cellMaxDate) {
            return isDateSmaller(cellMinDate, minDate) || isDateBigger(cellMaxDate, maxDate);
        }

        if (minDate && cellMinDate) {
            return isDateSmaller(cellMinDate, minDate);
        }

        if (maxDate && cellMaxDate) {
            return isDateBigger(cellMaxDate, maxDate);
        }

        return false;
    }

    destroy(): void {
        this.unbindDatepickerEvents();
    }

    focus = (): void => {
        this.$cell.classList.add('-focus-');
        this.focused = true;
    }

    removeFocus = (): void => {
        this.$cell.classList.remove('-focus-');
        this.focused = false;
    }

    select = (): void => {
        this.$cell.classList.add('-selected-');
        this.selected = true;
    }

    removeSelect = (): void => {
        this.$cell.classList.remove('-selected-', '-range-from-', '-range-to-');
        this.selected = false;
    }

    _handleRangeStatus(): void {
        const { selectedDates, focusDate, rangeDateTo, rangeDateFrom } = this.dp;
        const selectedDatesLen = selectedDates.length;

        this.$cell.classList.remove('-range-from-', '-range-to-', '-in-range-');

        if (!selectedDatesLen) return;

        let from = rangeDateFrom;
        let to = rangeDateTo;

        if (selectedDatesLen === 1 && focusDate) {
            const focusDateIsLargerThenSelected = isDateBigger(focusDate, selectedDates[0]);

            from = focusDateIsLargerThenSelected ? selectedDates[0] : focusDate;
            to = focusDateIsLargerThenSelected ? focusDate : selectedDates[0];
        }

        const classes = classNames({
            '-in-range-': from && to && isDateBetween(this.date, from, to),
            '-range-from-': from && isSameDate(this.date, from, this.type),
            '-range-to-': to && isSameDate(this.date, to, this.type)
        });

        if (classes) {
            this.$cell.classList.add(...classes.split(' '));
        }
    }

    _handleSelectedStatus(): void {
        const selected = this.dp._checkIfDateIsSelected(this.date, this.type);
        if (selected) {
            this.select();
        } else if (!selected && this.selected) {
            this.removeSelect();
        }
    }

    _handleInitialFocusStatus(): void {
        const datesAreSame = isSameDate(this.dp.focusDate, this.date, this.type);

        if (datesAreSame) {
            this.focus();
        }
    }

    _handleClasses(): void {
        // 1. Reset classes to a clean state
        this.$cell.setAttribute('class', '');

        // 2. Get base classes from the generator
        this.$cell.classList.add(...this._getClassName());

        // 3. Add state-based classes
        this._handleInitialFocusStatus();
        
        if (this.dp.selectedDates.length > 0) {
            this._handleSelectedStatus();
            if (this.dp.opts.range) {
                this._handleRangeStatus();
            }
        }
    }

    get isDisabled(): boolean {
        return this.$cell.matches('.-disabled-');
    }

    get isOtherMonth(): boolean {
        return this.dp.isOtherMonth(this.date);
    }

    get isOtherDecade(): boolean {
        return this.dp.isOtherDecade(this.date);
    }

    onChangeSelectedDate = (): void => {
        if (this.isDisabled) return;

        this._handleSelectedStatus();
        if (this.opts.range) {
            this._handleRangeStatus();
        }
    }

    onChangeFocusDate = (date: Date | false): void => {
        if (!date) {
            if (this.focused) {
                this.removeFocus();
            }
            return;
        }

        const datesAreSame = isSameDate(date, this.date, this.type);

        if (datesAreSame) {
            this.focus();
        } else if (!datesAreSame && this.focused) {
            this.removeFocus();
        }

        if (this.opts.range) {
            this._handleRangeStatus();
        }
    }

    render = (): HTMLElement => {
        this.$cell.innerHTML = this._getHtml();
        this._handleClasses();
        return this.$cell;
    }
}